SELECT json_build_object('values', COALESCE(json_agg(json_build_object('key', lower(s.name), 'value', CASE WHEN s.source = 'client' THEN COALESCE((SELECT f.setting FROM pg_file_settings f WHERE lower(f.name) = lower(s.name) AND f.applied ORDER BY f.seqno DESC LIMIT 1), s.boot_val) ELSE current_setting(s.name) END, 'pendingRestart', s.pending_restart) ORDER BY lower(s.name)), '[]')) FROM pg_settings s WHERE lower(s.name) = ANY (ARRAY[{!! collect($keys)->map($sql->string(...))->implode(', ') !!}]::text[]) OR s.pending_restart;
